    self._clock = clock
    self._promos: dict[str, PromoCode] = {}
    self._uses: dict[str, int] = {}
    self._customer_uses: dict[tuple[str, str], int] = {}

def add(self, promo: PromoCode) -> None:
    if promo.code in self._promos:
        raise ValidationError(f"duplicate promo code: {promo.code}")
    self._promos[promo.code] = promo

def resolve(self, raw_code: str, customer_id: str | None = None) -> PromoCode:
    """Find the code and check existence, validity period and usage limits, in this order."""
    promo = self._get(raw_code)
    now = self._clock.now()
    if (promo.starts_at is not None and now < promo.starts_at) or (
        promo.expires_at is not None and now >= promo.expires_at
    ):
        raise PromoExpiredError(f"promo code {promo.code} is not valid now")
    if promo.max_uses is not None and self._uses.get(promo.code, 0) >= promo.max_uses:
        raise PromoConditionsError(f"promo code {promo.code} has no uses left")
    if promo.max_uses_per_customer is not None:
        if customer_id is None:
            raise PromoConditionsError(f"promo code {promo.code} requires a customer")
        if self._customer_uses.get((promo.code, customer_id), 0) >= promo.max_uses_per_customer:
            raise PromoConditionsError(f"promo code {promo.code} has no uses left for this customer")
    return promo

def uses(self, raw_code: str, customer_id: str | None = None) -> int:
    """Total uses of the code, or uses by ``customer_id`` when it is given."""
    promo = self._get(raw_code)
    if customer_id is None:
        return self._uses.get(promo.code, 0)
    return self._customer_uses.get((promo.code, customer_id), 0)

def record_use(self, raw_code: str, customer_id: str | None = None) -> None:
    promo = self._get(raw_code)
    self._uses[promo.code] = self._uses.get(promo.code, 0) + 1
    if customer_id is not None:
        key = (promo.code, customer_id)
        self._customer_uses[key] = self._customer_uses.get(key, 0) + 1

def release_use(self, raw_code: str, customer_id: str | None = None) -> None:
    """Return one use; no count ever drops below zero."""
    promo = self._get(raw_code)
    self._uses[promo.code] = max(0, self._uses.get(promo.code, 0) - 1)
    if customer_id is not None:
        key = (promo.code, customer_id)
        self._customer_uses[key] = max(0, self._customer_uses.get(key, 0) - 1)

